#[cfg(not(target_arch = "wasm32"))]
#[derive(Clone)]
#[magnus::wrap(class = "Hacienda::EntityGlossary")]
pub struct EntityGlossary {
    inner: Arc<std::sync::Mutex<hacienda::glossary::EntityGlossary>>,
}

#[cfg(not(target_arch = "wasm32"))]
unsafe impl IntoValueFromNative for EntityGlossary {}

#[cfg(not(target_arch = "wasm32"))]
impl magnus::TryConvert for EntityGlossary {
    fn try_convert(val: magnus::Value) -> Result<Self, magnus::Error> {
        let r: &EntityGlossary = magnus::TryConvert::try_convert(val)?;
        Ok(r.clone())
    }
}

#[cfg(not(target_arch = "wasm32"))]
unsafe impl TryConvertOwned for EntityGlossary {}

#[cfg(not(target_arch = "wasm32"))]
impl EntityGlossary {
    fn observe(&self, text: String, entities: Vec<MergedEntity>) -> () {
        let entities_core: Vec<hacienda::MergedEntity> = entities.into_iter().map(Into::into).collect();
        self.inner.lock().unwrap().observe(&text, &entities_core)
    }

    fn entries(&self) -> Vec<GlossaryEntry> {
        self.inner
            .lock()
            .unwrap()
            .entries()
            .into_iter()
            .map(Into::into)
            .collect()
    }

    fn is_empty(&self) -> bool {
        self.inner.lock().unwrap().is_empty()
    }

    fn link(&self, text: String) -> String {
        self.inner.lock().unwrap().link(&text)
    }

    fn to_markdown(&self) -> String {
        self.inner.lock().unwrap().to_markdown()
    }
}

