#[cfg(not(target_arch = "wasm32"))]
impl FileSink {
    fn chain(&self) -> AuditChain {
        AuditChain {
            inner: Arc::new(std::sync::Mutex::new(self.inner.lock().unwrap().chain().clone())),
        }
    }

    fn chain_mut(&self) -> AuditChain {
        AuditChain {
            inner: Arc::new(std::sync::Mutex::new(self.inner.lock().unwrap().chain_mut().clone())),
        }
    }

    fn write(&self, entry: AuditEntry) -> Result<(), Error> {
        let entry_core: hacienda::AuditEntry = entry.into();
        self.inner.lock().unwrap().write(&entry_core).map_err(alef_magnus_err)?;
        Ok(())
    }

    fn flush(&self) -> Result<(), Error> {
        self.inner.lock().unwrap().flush().map_err(alef_magnus_err)?;
        Ok(())
    }

    fn rotate(&self) -> Result<(), Error> {
        self.inner.lock().unwrap().rotate().map_err(alef_magnus_err)?;
        Ok(())
    }
}

