#[derive(Clone)]
#[magnus::wrap(class = "Hacienda::NerDetector")]
pub struct NerDetector {
    inner: Arc<hacienda::pii::NerDetector>,
}

unsafe impl IntoValueFromNative for NerDetector {}

impl magnus::TryConvert for NerDetector {
    fn try_convert(val: magnus::Value) -> Result<Self, magnus::Error> {
        let r: &NerDetector = magnus::TryConvert::try_convert(val)?;
        Ok(r.clone())
    }
}

unsafe impl TryConvertOwned for NerDetector {}

impl NerDetector {
    fn runtime_state(&self) -> NerRuntimeState {
        self.inner.runtime_state().into()
    }

    fn with_threshold(&self, threshold: f32) -> NerDetector {
        Self {
            inner: Arc::new(self.inner.as_ref().clone().with_threshold(threshold)),
        }
    }

    fn detect_async(&self, text: String) -> Result<Vec<ModelEntity>, Error> {
        let inner = self.inner.clone();
        // 16 MiB: tokio's ~2 MB default worker stack can overflow on a deep
        // extraction future (a nested archive member, a multi-stage OCR pipeline), and a
        // stack overflow aborts the process with SIGBUS instead of raising a catchable panic.
        const ASYNC_METHOD_RUNTIME_STACK_SIZE_BYTES: usize = 16 * 1024 * 1024;
        let rt = tokio::runtime::Builder::new_multi_thread()
            .enable_all()
            .thread_stack_size(ASYNC_METHOD_RUNTIME_STACK_SIZE_BYTES)
            .build()
            .map_err(alef_magnus_err)?;
        let result = rt
            .block_on(async { inner.detect(&text).await })
            .map_err(alef_magnus_err)?;
        Ok(result.into_iter().map(Into::into).collect())
    }
}

