#[derive(Clone)]
#[magnus::wrap(class = "Hacienda::Segment")]
pub struct Segment {
    inner: Arc<std::sync::Mutex<hacienda::audit::Segment>>,
}

unsafe impl IntoValueFromNative for Segment {}

impl magnus::TryConvert for Segment {
    fn try_convert(val: magnus::Value) -> Result<Self, magnus::Error> {
        let r: &Segment = magnus::TryConvert::try_convert(val)?;
        Ok(r.clone())
    }
}

unsafe impl TryConvertOwned for Segment {}

impl Segment {
    fn push(&self, input: AuditEntryInput) -> AuditEntry {
        let input_core: hacienda::AuditEntryInput = input.into();
        self.inner.lock().unwrap().push(input_core).clone().into()
    }

    fn seal(&self) -> SegmentSeal {
        self.inner.as_ref().clone().seal().into()
    }

    fn id(&self) -> String {
        self.inner.lock().unwrap().id().into()
    }

    fn node_id(&self) -> NodeId {
        NodeId {
            inner: Arc::new(self.inner.lock().unwrap().node_id().clone()),
        }
    }

    fn tenant_id(&self) -> TenantId {
        TenantId {
            inner: Arc::new(self.inner.lock().unwrap().tenant_id().clone()),
        }
    }

    fn tip(&self) -> String {
        self.inner.lock().unwrap().tip().into()
    }

    fn len(&self) -> usize {
        self.inner.lock().unwrap().len()
    }

    fn is_empty(&self) -> bool {
        self.inner.lock().unwrap().is_empty()
    }

    fn entries(&self) -> Vec<AuditEntry> {
        self.inner
            .lock()
            .unwrap()
            .entries()
            .iter()
            .map(|v| v.clone().into())
            .collect()
    }

    fn append(&self, entry: AuditEntry) -> Result<(), Error> {
        let entry_core: hacienda::AuditEntry = entry.into();
        self.inner.lock().unwrap().append(entry_core).map_err(alef_magnus_err)?;
        Ok(())
    }

    fn verify(&self) -> Result<(), Error> {
        self.inner.lock().unwrap().verify().map_err(alef_magnus_err)?;
        Ok(())
    }
}

