#[derive(Clone)]
#[magnus::wrap(class = "Hacienda::TenantPseudonymiserRegistry")]
pub struct TenantPseudonymiserRegistry {
    inner: Arc<hacienda::redaction::pseudonym::TenantPseudonymiserRegistry>,
}

unsafe impl IntoValueFromNative for TenantPseudonymiserRegistry {}

impl magnus::TryConvert for TenantPseudonymiserRegistry {
    fn try_convert(val: magnus::Value) -> Result<Self, magnus::Error> {
        let r: &TenantPseudonymiserRegistry = magnus::TryConvert::try_convert(val)?;
        Ok(r.clone())
    }
}

unsafe impl TryConvertOwned for TenantPseudonymiserRegistry {}

impl TenantPseudonymiserRegistry {
    fn admit(
        &self,
        tenant: TenantId,
        resolver: KeyResolver,
        active: Option<KeyId>,
        retired: Option<Vec<KeyId>>,
    ) -> Result<(), Error> {
        let retired_core: Vec<hacienda::KeyId> = retired.into_iter().map(Into::into).collect();
        self.inner
            .admit(
                &tenant.inner,
                &resolver.inner,
                active.as_ref().map(|v| &v.inner),
                &retired_core,
            )
            .map_err(alef_magnus_err)?;
        Ok(())
    }

    fn get(&self, tenant: TenantId) -> Option<Pseudonymiser> {
        self.inner
            .get(&tenant.inner)
            .map(|v| Pseudonymiser { inner: Arc::new(v) })
    }

    fn contains(&self, tenant: TenantId) -> bool {
        self.inner.contains(&tenant.inner)
    }
}

