fn build_editor_projection(document: magnus::Value, options: magnus::Value) -> Result<EditorEnvelope, Error> {
    let document_core: xberg::ExtractedDocument = {
        let binding_val: ExtractedDocument = ExtractedDocument::try_convert(document).map_err(|e| {
            magnus::Error::new(
                unsafe { Ruby::get_unchecked() }.exception_runtime_error(),
                e.to_string(),
            )
        })?;
        binding_val.into()
    };
    let options_core: hacienda::editor_projection::EditorProjectionOptions = {
        let binding_val: EditorProjectionOptions = EditorProjectionOptions::try_convert(options).map_err(|e| {
            magnus::Error::new(
                unsafe { Ruby::get_unchecked() }.exception_runtime_error(),
                e.to_string(),
            )
        })?;
        binding_val.into()
    };
    Ok(hacienda::editor_projection::build_editor_projection(&document_core, &options_core).into())
}

