fn compute_seal_hash(args: &[magnus::Value]) -> Result<String, Error> {
    let args = magnus::scan_args::scan_args::<
        (),
        (
            Option<magnus::Value>,
            Option<magnus::Value>,
            Option<magnus::Value>,
            Option<magnus::Value>,
            Option<magnus::Value>,
            Option<magnus::Value>,
            Option<magnus::Value>,
            Option<magnus::Value>,
            Option<magnus::Value>,
        ),
        (),
        (),
        (),
        (),
    >(args)?;
    let (prev_seal_hash, segment_id, tenant_id, node_id, config_hash, sealed_tip, entry_count, opened_at, sealed_at) =
        args.optional;

    let prev_seal_hash: Option<String> = match prev_seal_hash {
        Some(v) if !v.is_nil() => Some(String::try_convert(v)?),
        _ => None,
    };

    let segment_id: Option<String> = match segment_id {
        Some(v) if !v.is_nil() => Some(String::try_convert(v)?),
        _ => None,
    };

    let tenant_id: Option<String> = match tenant_id {
        Some(v) if !v.is_nil() => Some(String::try_convert(v)?),
        _ => None,
    };

    let node_id: Option<String> = match node_id {
        Some(v) if !v.is_nil() => Some(String::try_convert(v)?),
        _ => None,
    };

    let config_hash: Option<String> = match config_hash {
        Some(v) if !v.is_nil() => Some(String::try_convert(v)?),
        _ => None,
    };

    let sealed_tip: Option<String> = match sealed_tip {
        Some(v) if !v.is_nil() => Some(String::try_convert(v)?),
        _ => None,
    };

    let entry_count: Option<u64> = match entry_count {
        Some(v) if !v.is_nil() => Some(u64::try_convert(v)?),
        _ => None,
    };

    let opened_at: Option<String> = match opened_at {
        Some(v) if !v.is_nil() => Some(String::try_convert(v)?),
        _ => None,
    };

    let sealed_at: Option<String> = match sealed_at {
        Some(v) if !v.is_nil() => Some(String::try_convert(v)?),
        _ => None,
    };

    Ok(hacienda::audit::compute_seal_hash(
        prev_seal_hash.as_deref(),
        &segment_id.expect("'segment_id' is required"),
        &tenant_id.expect("'tenant_id' is required"),
        &node_id.expect("'node_id' is required"),
        &config_hash.expect("'config_hash' is required"),
        &sealed_tip.expect("'sealed_tip' is required"),
        entry_count.expect("'entry_count' is required"),
        &opened_at.expect("'opened_at' is required"),
        &sealed_at.expect("'sealed_at' is required"),
    ))
}

#[cfg(not(target_arch = "wasm32"))]
fn detect_mime_type(args: &[magnus::Value]) -> Result<String, Error> {
    let args = magnus::scan_args::scan_args::<(Vec<u8>,), (Option<magnus::Value>,), (), (), (), ()>(args)?;
    let (bytes,) = args.required;

    let (filename,) = args.optional;

    let filename: Option<String> = match filename {
        Some(v) if !v.is_nil() => Some(String::try_convert(v)?),
        _ => None,
    };

    let result = hacienda::xberg_surface::detect_mime_type(&bytes, filename.as_deref()).map_err(alef_magnus_err)?;
    Ok(result)
}

