#[allow(unused_variables)]
fn merge_entities(args: &[magnus::Value]) -> Result<Vec<MergedEntity>, Error> {
    let args =
        magnus::scan_args::scan_args::<(Vec<RegexEntity>, Vec<ModelEntity>), (Option<magnus::Value>,), (), (), (), ()>(
            args,
        )?;
    let (regex_entities, model_entities) = args.required;

    let (config,) = args.optional;

    let regex_entities_core: Vec<hacienda::pii::RegexEntity> = regex_entities.into_iter().map(Into::into).collect();
    let model_entities_core: Vec<hacienda::pii::ModelEntity> = model_entities.into_iter().map(Into::into).collect();
    let config_core: hacienda::pii::MergeConfig = match config {
        Some(_v) if !_v.is_nil() => {
            let binding_val: MergeConfig = MergeConfig::try_convert(_v).map_err(|e| {
                magnus::Error::new(
                    unsafe { Ruby::get_unchecked() }.exception_runtime_error(),
                    e.to_string(),
                )
            })?;
            binding_val.into()
        }
        _ => Default::default(),
    };
    Ok(
        hacienda::pii::merge_entities(regex_entities_core, model_entities_core, &config_core)
            .into_iter()
            .map(Into::into)
            .collect(),
    )
}

