fn report(
    version: String,
    embedding_compiled: bool,
    onnx_runtime: magnus::Value,
    service_ready: bool,
    ner: magnus::Value,
) -> Result<CapabilityReport, Error> {
    let onnx_runtime: hacienda::capabilities::CapabilityStatus = {
        let binding_val: CapabilityStatus = CapabilityStatus::try_convert(onnx_runtime)
            .map_err(|e| magnus::Error::new(unsafe { Ruby::get_unchecked() }.exception_type_error(), e.to_string()))?;
        binding_val.into()
    };
    let ner: hacienda::pii::NerRuntimeState = {
        let binding_val: NerRuntimeState = NerRuntimeState::try_convert(ner)
            .map_err(|e| magnus::Error::new(unsafe { Ruby::get_unchecked() }.exception_type_error(), e.to_string()))?;
        binding_val.into()
    };
    Ok(hacienda::capabilities::report(
        &version,
        embedding_compiled,
        onnx_runtime.into(),
        service_ready,
        ner.into(),
    )
    .into())
}

