#[cfg(any(not(feature = "rag-embeddings"), feature = "rag-embeddings"))]
fn warm_embedding_preset(name: String) -> Result<WarmResult, Error> {
    let async_result = alef_magnus_run_without_gvl(move || -> Result<_, String> {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .map_err(|e| e.to_string())?;
        Ok(rt.block_on(async { hacienda::xberg_surface::warm_embedding_preset(&name).await }))
    });
    let result = async_result
        .map_err(|message| magnus::Error::new(unsafe { Ruby::get_unchecked() }.exception_runtime_error(), message))?;
    let result = result.map_err(alef_magnus_err)?;
    Ok(result.into())
}

#[cfg(any(not(feature = "rag-embeddings"), feature = "rag-embeddings"))]
fn warm_embedding_preset_async(name: String) -> Result<WarmResult, Error> {
    let async_result = alef_magnus_run_without_gvl(move || -> Result<_, String> {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .map_err(|e| e.to_string())?;
        Ok(rt.block_on(async { hacienda::xberg_surface::warm_embedding_preset(&name).await }))
    });
    let result = async_result
        .map_err(|message| magnus::Error::new(unsafe { Ruby::get_unchecked() }.exception_runtime_error(), message))?;
    let result = result.map_err(alef_magnus_err)?;
    Ok(result.into())
}

